mapper.select:
SELECT sst.*, (SELECT sys_dict_item_name FROM sys_dict_item WHERE sys_dict_item_id = sst.sys_email_template_category) sysEmailTemplateCategoryLabel FROM sys_email_template sst WHERE sys_project_id = #{request.sysProjectId}
AND sys_email_template_content LIKE CONCAT(#{request.sysEmailTemplateContent}, '%')
ORDER BY sst.sys_email_template_sort
